    Bug 1969229 - Query the correct interface when syncing an outgoing server removal. r=mkmelin

    While testing this, I've also realised the EWS outgoing server didn't behave
    correctly when queried about its UID if it didn't have one already. It seems
    like the expectation is for the `nsIMsgOutgoingServer` implementation itself to
    generate one if none exist, whereas `EwsOutgoingServer` was expecting it to be
    set from an outside source.

    Differential Revision: https://phabricator.services.mozilla.com/D251687

diff --git a/mail/services/sync/modules/engines/servers.sys.mjs b/mail/services/sync/modules/engines/servers.sys.mjs
index 7034ac2e116..a42a236284d 100644
--- a/mail/services/sync/modules/engines/servers.sys.mjs
+++ b/mail/services/sync/modules/engines/servers.sys.mjs
@@ -371,7 +371,7 @@ ServerTracker.prototype = {
       server = subject.QueryInterface(Ci.nsIMsgIncomingServer);
       this.engine._store.markDeleted(server.UID);
     } else if (topic == "message-smtpserver-removed") {
-      server = subject.QueryInterface(Ci.nsISmtpServer);
+      server = subject.QueryInterface(Ci.nsIMsgOutgoingServer);
       this.engine._store.markDeleted(server.UID);
     } else {
       const [, group, serverKey] = data.split(".", 3);
diff --git a/rust/ews_xpcom/src/outgoing.rs b/rust/ews_xpcom/src/outgoing.rs
index d8a2f94d225..2e63809f74d 100644
--- a/rust/ews_xpcom/src/outgoing.rs
+++ b/rust/ews_xpcom/src/outgoing.rs
@@ -15,6 +15,7 @@ use nserror::nsresult;
 use nserror::NS_OK;
 use nsstring::{nsACString, nsCString, nsString};
 use url::Url;
+use uuid::Uuid;
 use xpcom::interfaces::{nsILoginInfo, nsILoginManager};
 use xpcom::{create_instance, get_service, getter_addrefs, nsIID};
 use xpcom::{
@@ -378,9 +379,18 @@ impl EwsOutgoingServer {
         let uid = match uid {
             Some(uid) => uid.clone(),
             None => {
-                let uid = self
-                    .read_string_pref(PrefName::Uid)?
-                    .ok_or(nserror::NS_ERROR_NOT_INITIALIZED)?;
+                let uid = match self.read_string_pref(PrefName::Uid)? {
+                    Some(uid) => uid,
+                    None => {
+                        // If no UID has been generated for this server yet,
+                        // generate one and store it to the server's prefs, then
+                        // return it.
+                        let uid = Uuid::new_v4().hyphenated().to_string();
+                        let uid = nsCString::from(uid);
+                        self.store_string_pref(PrefName::Uid, &*uid)?;
+                        uid
+                    }
+                };

                 // We don't need to check whether the return value is an error,
                 // since this code only runs if the UID wasn't already set.
